SELECT DISTINCT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind FROM drug_indication di JOIN molecule_dictionary md ON di.molregno = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE di.max_phase_for_ind = 4 AND di.efo_term = 'chronic kidney disease' ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, indication_curie, indication_label, di.max_phase_for_ind
